  function renderHome(){ app.innerHTML = `<section class="hero"><div class="eyebrow">SCHOOLPILOT</div><h1>授業準備教材を探す</h1><p>学年・教科・教科書出版社を選ぶと、対応する単元を表示します。</p></section><div class="section-title"><h2>学年を選ぶ</h2></div><div class="grade-grid">${gradeOptions.map(g=>`<button class="choice ${g===state.grade?'selected':''}" data-grade="${g}"><strong>${g}</strong></button>`).join('')}</div><div class="section-title"><h2>教科を選ぶ</h2></div><div class="subject-grid">${subjects.map(s=>`<button class="choice ${s===state.subject?'selected':''}" data-subject="${s}"><strong>${s}</strong></button>`).join('')}</div><div class="section-title"><h2>教科書の出版社を選ぶ</h2><p>${state.grade}・${state.subject}</p></div><div class="publisher-grid">${publishers.map(p=>`<button class="choice ${p===state.publisher?'selected':''}" data-publisher="${p}"><strong>${p}</strong></button>`).join('')}</div><p class="publisher-note">単元一覧は、文部科学省の教科書制度および各出版社の公開資料を参考に同梱しています。学校の採択版・年度によって配列や名称が異なる場合があります。</p><div class="section-title"><h2>単元を選ぶ</h2><p>${state.publisher}の公開単元配列を参考</p></div><div class="unit-grid">${selectedUnits().map(u=>`<button class="unit-card" data-unit="${u}"><strong>${u}</strong></button>`).join('')}</div>`; }
  function renderHome(){ const unitList=selectedUnits(); const ready=Boolean(state.grade&&state.subject&&state.publisher&&state.unit); app.innerHTML = `<section class="hero"><div class="eyebrow">SCHOOLPILOT</div><h1>授業準備教材を探す</h1><p>学年・教科・教科書出版社・単元を選んでください。</p></section><div class="section-title"><h2>学年を選ぶ</h2></div><div class="grade-grid">${gradeOptions.map(g=>`<button class="choice ${g===state.grade?'selected':''}" data-grade="${g}"><strong>${g}</strong></button>`).join('')}</div><div class="section-title"><h2>教科を選ぶ</h2></div><div class="subject-grid">${subjects.map(s=>`<button class="choice ${s===state.subject?'selected':''}" data-subject="${s}"><strong>${s}</strong></button>`).join('')}</div><div class="section-title"><h2>教科書の出版社を選ぶ</h2><p>${state.grade}・${state.subject}</p></div><div class="publisher-grid">${publishers.map(p=>`<button class="choice ${p===state.publisher?'selected':''}" data-publisher="${p}"><strong>${p}</strong></button>`).join('')}</div><p class="publisher-note">単元一覧は、文部科学省の教科書制度および各出版社の公開資料を参考に同梱しています。学校の採択版・年度によって配列や名称が異なる場合があります。</p><div class="section-title"><h2>単元を選ぶ</h2><p>${state.publisher}の公開単元配列を参考</p></div><div class="unit-grid">${unitList.map(u=>`<button class="unit-card ${u===state.unit?'selected':''}" data-unit="${u}"><strong>${u}</strong></button>`).join('')}</div><div class="home-search"><button class="primary search-button" data-search ${ready?'':'disabled'}>検索</button>${ready?'':'<p class="search-note">学年・教科・出版社・単元をすべて選択してください。</p>'}</div>`; }
  function loadReviewSaved(){ try{return JSON.parse(localStorage.getItem('schoolpilot-review-tests')||'[]');}catch(e){return [];} }
  function loadSupportSaved(){ try{return JSON.parse(localStorage.getItem('schoolpilot-support-materials')||'[]');}catch(e){return [];} }
  function renderDesk(){ const tests=loadSaved(), reviews=loadReviewSaved(); const cards=(items,kind,offset,store)=>items.map((x,i)=>`<article class="desk-card"><h3>${x.title||`${x.grade} ${x.subject}「${x.unit}」`}</h3><p>${kind} / ${x.level} / ${x.items.length}問</p><div class="actions"><button class="secondary" data-open-saved="${offset+i}" data-open-store="${store}" style="margin-top:12px">元のデータを開く</button><button class="secondary" data-rename-saved="${i}" data-rename-store="${store}" style="margin-top:12px">名前変更</button><button class="danger" data-delete-saved="${i}" data-delete-store="${store}" style="margin-top:12px">削除</button></div></article>`).join(''); app.innerHTML = `<section class="hero"><div class="eyebrow">MY TEACHING DESK</div><h1>マイ授業デスク</h1><p>保存したテストをクリックすると、元の作成画面に戻れます。</p></section><div class="desk-category"><div class="section-title"><h2>小テスト</h2><p>${tests.length}件</p></div>${tests.length?`<div class="desk-grid">${cards(tests,'小テスト',0,'test')}</div>`:'<div class="empty">小テストの保存データはありません。</div>'}</div><div class="desk-category"><div class="section-title"><h2>復習テスト</h2><p>${reviews.length}件</p></div>${reviews.length?`<div class="desk-grid">${cards(reviews,'復習テスト',0,'review')}</div>`:'<div class="empty">復習テストの保存データはありません。</div>'}</div>`; }
  function deleteSaved(store,index){ const key=store==='review'?'schoolpilot-review-tests':STORAGE_KEY; const items=store==='review'?loadReviewSaved():loadSaved(); if(!items[index])return; if(!window.confirm('この保存データを削除しますか？'))return; items.splice(index,1); localStorage.setItem(key,JSON.stringify(items)); render(); }
  function renderSupportDesk(){ if(state.page!=='desk'||!el('.container')||el('#support-desk-category'))return; const items=loadSupportSaved(); const box=document.createElement('div');box.id='support-desk-category';box.className='desk-category';box.innerHTML=`<div class="section-title"><h2>指導案・板書例</h2><p>${items.length}件</p></div>${items.length?`<div class="desk-grid">${items.map((x,i)=>`<article class="desk-card"><h3>${x.title}</h3><p>${x.level} / ${x.type==='board'?'板書例':'指導案・授業展開例'}</p><div class="actions"><button class="secondary" data-open-support="${i}" style="margin-top:12px">元のデータを開く</button><button class="danger" data-delete-support="${i}" style="margin-top:12px">削除</button></div></article>`).join('')}</div>`:'<div class="empty">保存した指導案・板書例はありません。</div>'}`;el('.container').appendChild(box); }
  function renameSaved(store,index){ const key=store==='review'?'schoolpilot-review-tests':STORAGE_KEY; const items=store==='review'?loadReviewSaved():loadSaved(); if(!items[index])return; const current=items[index].title||`${items[index].grade} ${items[index].subject}「${items[index].unit}」`; const title=window.prompt('保存名を入力してください。',current); if(title===null||!title.trim())return; items[index].title=title.trim(); localStorage.setItem(key,JSON.stringify(items)); render(); }
  function renderDetail(){ app.innerHTML = `<div class="crumbs">ホーム / ${state.grade} / ${state.subject}</div><section class="panel"><div class="unit-head"><div><span class="pill">${state.grade}・${state.subject}</span><h1>「${state.unit}」</h1></div><button class="secondary" data-page="home">単元一覧に戻る</button></div><div class="tabs"><button class="tab active">単元概要</button><button class="tab">45分授業案</button><button class="tab">AI板書</button><button class="tab active">AIミニテスト</button></div><p class="notice">授業レベルを選び、必要な素材のボタンを押してください。MVPではブラウザ内テンプレートから生成します。</p><div class="levels">${levels.map(l=>`<button class="level ${l===state.level?'selected':''}" data-level="${l}">${l}</button>`).join('')}</div><div class="feature"><h2>AI授業案生成 MVP</h2><p>学習目標・授業の流れ・発問・つまずき対応をまとめます。</p><div class="actions"><button class="secondary" data-demo="lesson">45分授業案を生成</button><button class="secondary" data-demo="board">板書案を生成</button></div></div><div class="feature test"><h2>AIミニテスト生成 MVP</h2><p>約5問の選択式・短答・説明問題を、正答とやさしい解説つきで作成します。</p><div class="actions"><button class="primary" id="generate-test">ミニテストを生成</button></div><div id="test-result"></div></div><div class="feature"><h2>AIワークシート生成 MVP</h2><p>児童向けの問題プリントを5問作成します。名前欄つきで、そのまま印刷できます。</p><div class="actions"><button class="primary" id="generate-worksheet">ワークシートを生成</button></div><div id="worksheet-result"></div></div></section>`; }
  function renderDetail(){ app.innerHTML=`<div class="crumbs">ホーム / ${state.grade} / ${state.subject}</div><section class="panel"><div class="unit-head"><div><span class="pill">${state.grade}・${state.subject}</span><h1>「${state.unit}」</h1></div><button class="secondary" data-page="home">ホームに戻る</button></div><div class="tabs"><button class="tab" data-tab="overview">単元概要</button><button class="tab" data-tab="lesson">授業指導案</button><button class="tab" data-tab="board">板書</button><button class="tab" data-tab="test">テスト</button></div><div id="tab-content"></div></section>`; renderActiveTab(); }
  function clearGeneratedContent(){ document.querySelectorAll('#support-result').forEach(n=>n.remove()); state.result=null; state.worksheetResult=null; }
  function renderPackSection(){ return; }
  function renderOverview(){ const pane=el('#tab-content'); if(!pane)return; const ratio=state.grade==='5年'&&state.subject==='算数'&&state.unit==='割合'; const purpose=ratio?'割合を、もとにする量を1とみたときの比べられる量の大きさとして理解し、割合・比べられる量・もとにする量の関係を数・式・数直線で説明できるようにする。':`${state.unit}の基礎的な知識と技能を身に付け、学んだ考え方を使って問題を解決し、理由を説明できるようにする。`; const knowledge=ratio?'割合の意味、百分率、小数との関係を理解している。':`${state.unit}の用語・きまり・基本的な方法を理解している。`; const thinking=ratio?'何をもとにする量とするかを判断し、数直線や式を使って考え方を説明している。':'図・式・言葉を使って考え方を表し、結果を振り返っている。'; const attitude='見通しをもって取り組み、友達の考えと比べながら自分の考えを修正・説明しようとしている。'; const result=ratio?'割合を小数や百分率で表し、割合・比べられる量・もとにする量を求める問題を解決できる。':'学習した内容を使って基本問題と活用問題を解き、学んだことを自分の言葉で振り返ることができる。'; pane.innerHTML=`<div class="overview-card"><span class="pill">指導要領・学習評価を参照</span><h2>単元の目的</h2><p>${purpose}</p><h2>評価の観点</h2><div class="evaluation-grid"><div><b>知識・技能</b><p>${knowledge}</p></div><div><b>思考・判断・表現</b><p>${thinking}</p></div><div><b>主体的に学習に取り組む態度</b><p>${attitude}</p></div></div><h2>学習後に期待する結果</h2><p>${result}</p><p class="source-note">参照：<a href="https://www.mext.go.jp/content/20211102-mxt_kyoiku02-100002607_04.pdf" target="_blank" rel="noopener">文部科学省 小学校学習指導要領解説 算数編</a> ／ <a href="https://www.mext.go.jp/b_menu/hakusho/nc/1415169.htm" target="_blank" rel="noopener">文部科学省 学習評価の通知</a></p></div>`; }
  function renderActiveTab(){ const pane=el('#tab-content'); if(!pane)return; clearGeneratedContent(); document.querySelectorAll('.tab').forEach(t=>t.classList.toggle('active',t.dataset.tab===state.activeTab)); const levelHtml=`<p class="notice">授業レベルを選び、選択した内容を作成してください。ブラウザ内テンプレートで生成します。</p><div class="levels">${levels.map(l=>`<button class="level ${l===state.level?'selected':''}" data-level="${l}">${l}</button>`).join('')}</div>`; if(state.activeTab==='overview'){pane.innerHTML=`<div class="feature"><h2>単元概要</h2><p>${state.grade} ${state.subject}「${state.unit}」の学習内容を確認し、授業案・板書・テストを準備できます。</p><div class="overview-points"><span>学習内容を整理</span><span>授業時間に合わせて設計</span><span>印刷・保存に対応</span></div></div>`;renderOverview();} else if(state.activeTab==='lesson'){pane.innerHTML=`${levelHtml}<div class="feature"><h2>授業案</h2><p>15分・30分・45分から授業時間を選び、${state.unit}の学習内容を段階的に扱います。</p><div class="minutes">${[15,30,45].map(m=>`<button class="level ${m===state.lessonMinutes?'selected':''}" data-minutes="${m}">${m}分</button>`).join('')}</div><div class="actions"><button class="primary" data-demo="lesson">授業案を作成</button></div></div>`;} else if(state.activeTab==='board'){pane.innerHTML=`${levelHtml}<div class="feature"><h2>板書</h2><p>めあて・問題・考え方・まとめを、黒板の流れに沿って整理します。</p><div class="actions"><button class="primary" data-demo="board">板書例を作成</button></div></div>`;} else {pane.innerHTML=`${levelHtml}<div class="feature test"><h2>小テスト</h2><p>約5問の問題と正答・やさしい解説を作成します。</p><div class="actions"><button class="primary" id="generate-test">小テストを生成</button></div><div id="test-result"></div></div><div class="feature"><h2>復習テスト</h2><p>小テストとは別の問題で、理解の定着を確認します。</p><div class="actions"><button class="primary" id="generate-worksheet">復習テストを生成</button></div><div id="worksheet-result"></div></div>`;} applyLabels(); renderPackSection(); }
  function renderReferences(container,title='参考情報',kind='overview'){ const key=`${state.grade}|${state.subject}|${state.unit}`; const links=(unitReferences[key]&&unitReferences[key][kind])||generalReferenceByKind[kind]||referenceInfo[state.subject]||referenceInfo['算数']; container.insertAdjacentHTML('beforeend',`<div class="reference-card"><h2>${title}</h2><p>この単元・用途に合わせた公開資料です。リンク先の利用条件と学校の採択教科書をご確認ください。</p><div class="reference-grid">${links.map(x=>`<a href="${x[1]}" target="_blank" rel="noopener">${x[0]}<span>公開ページを開く ↗</span></a>`).join('')}</div></div>`); }
  function renderActiveTab(){ const pane=el('#tab-content'); if(!pane)return; clearGeneratedContent(); document.querySelectorAll('.tab').forEach(t=>t.classList.toggle('active',t.dataset.tab===state.activeTab)); const levelHtml=`<p class="notice">授業レベルを選び、選択した内容を作成してください。ブラウザ内テンプレートで生成します。</p><div class="levels">${levels.map(l=>`<button class="level ${l===state.level?'selected':''}" data-level="${l}">${l}</button>`).join('')}</div>`; if(state.activeTab==='overview'){pane.innerHTML=`<div class="feature"><h2>単元概要</h2><p>${state.grade} ${state.subject}「${state.unit}」の学習内容を確認し、授業案・板書・テストを準備できます。</p><div class="overview-points"><span>学習内容を整理</span><span>授業時間に合わせて設計</span><span>印刷・保存に対応</span></div></div>`;renderOverview();renderReferences(pane,'単元研究・参考情報','overview');} else if(state.activeTab==='lesson'){pane.innerHTML=`${levelHtml}<div class="feature"><h2>授業案（授業指導案）</h2><p>単元の目標、本時の展開、教師の支援、評価と振り返りをつなげて作成します。</p><div class="minutes">${[15,30,45].map(m=>`<button class="level ${m===state.lessonMinutes?'selected':''}" data-minutes="${m}">${m}分</button>`).join('')}</div><div class="actions"><button class="primary" data-demo="lesson">授業案を作成</button></div></div>`;renderReferences(pane,'授業案・指導案の参考情報','lesson');} else if(state.activeTab==='board'){pane.innerHTML=`${levelHtml}<div class="feature"><h2>板書</h2><p>${state.subject}「${state.unit}」の学習過程に合わせた板書例を作成します。</p><div class="actions"><button class="primary" data-demo="board">板書例を作成</button></div></div>`;renderReferences(pane,'板書づくりの参考情報','board');} else {pane.innerHTML=`${levelHtml}<div class="feature test"><h2>小テスト</h2><p>約5問の問題と正答・やさしい解説を作成します。</p><div class="actions"><button class="primary" id="generate-test">小テストを生成</button></div><div id="test-result"></div></div><div class="feature"><h2>復習テスト</h2><p>小テストとは別の問題で、理解の定着を確認します。</p><div class="actions"><button class="primary" id="generate-worksheet">復習テストを生成</button></div><div id="worksheet-result"></div></div>`;pane.insertAdjacentHTML('beforeend',researchBasis);renderReferences(pane,'テスト・教材研究の参考情報','test');} applyLabels(); renderPackSection(); }
  function loadSaved(){ try{return JSON.parse(localStorage.getItem(STORAGE_KEY)||'[]');}catch(e){return [];} }
  function saveToDesk(){
    if(!state.result||!state.result.items){ showMessage('先にミニテストを生成してください。'); return false; }
    try{
      const all=loadSaved().filter(x=>!(x.grade===state.grade&&x.subject===state.subject&&x.publisher===state.publisher&&x.unit===state.unit&&x.level===state.level));
      all.unshift({grade:state.grade,subject:state.subject,publisher:state.publisher,unit:state.unit,level:state.level,items:state.result.items,savedAt:new Date().toISOString()});
      localStorage.setItem(STORAGE_KEY,JSON.stringify(all.slice(0,20)));
      return true;
    }catch(e){ showMessage('保存できませんでした。ブラウザのプライベート設定をご確認ください。'); return false; }
  }
  function saveLocalFile(){
    if(!state.result||!state.result.items){ showMessage('先にミニテストを生成してください。'); return; }
    const payload={version:'v12',grade:state.grade,subject:state.subject,unit:state.unit,level:state.level,items:state.result.items,savedAt:new Date().toISOString()};
    const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'});
    const url=URL.createObjectURL(blob); const link=document.createElement('a');
    link.href=url; link.download=`${state.grade}_${state.subject}_${state.unit}_ミニテスト.json`;
    document.body.appendChild(link); link.click(); link.remove(); URL.revokeObjectURL(url);
    showMessage('ローカル保存しました。JSONファイルをダウンロードしました。');
  }
  function buildItems(){ const key=`${state.grade}|${state.subject}|${state.unit}`; if(testSets[key]) return testSets[key]; const base=genericTemplates[state.subject]||genericTemplates.算数; return Array.from({length:5},(_,i)=>({...base[i%base.length],question:`${state.unit}：${base[i%base.length].question}`})); }
  function renderTestResult(){ const r=state.result; if(!r)return; const html=`<div class="result"><h3>${state.grade} ${state.subject}「${state.unit}」のミニテスト（${state.level}）</h3>${researchBasis}${r.items.map((q,i)=>`<article class="question"><div class="question-head"><span class="qno">${i+1}</span><span class="format">${q.format}</span></div><p><strong>${q.question}</strong></p>${q.choices?`<p>${q.choices.map((c,j)=>`${String.fromCharCode(65+j)}．${c}`).join('　')}</p>`:''}<p class="answer">正答：${q.answer}</p><p class="explain">やさしい解説：${q.explain}</p></article>`).join('')}<div class="actions"><button class="primary" id="regenerate-test">作り直す</button><button class="secondary" id="copy-test">コピー</button><button class="secondary" id="save-desk">マイ授業デスクに保存</button><button class="secondary" id="save-local-pdf">PDFでローカル保存</button></div><p id="result-message" class="notice" hidden></p></div>`; el('#test-result').innerHTML=html; applyLabels(); }
  function applyLabels(){ document.querySelectorAll('*').forEach(n=>{if(n.childNodes.length===1&&n.firstChild.nodeType===3)n.textContent=n.textContent.replaceAll('AI','');}); document.querySelectorAll('h2').forEach(n=>{n.textContent=n.textContent.replace('ミニテスト生成 MVP','小テスト生成').replace('ワークシート生成 MVP','復習テスト生成');}); document.querySelectorAll('h3').forEach(n=>{n.textContent=n.textContent.replaceAll('ミニテスト','小テスト').replaceAll('ワークシート','復習テスト');}); document.querySelectorAll('button').forEach(n=>{n.textContent=n.textContent.replace('ミニテストを生成','小テストを生成').replace('ワークシートを生成','復習テストを生成');}); }
  function copyText(){
    if(!state.result||!state.result.items){ showMessage('先にミニテストを生成してください。'); return; }
    const text=state.result.items.map((q,i)=>`${i+1}. ${q.question}\n${q.choices?q.choices.join(' / ')+'\n':''}正答：${q.answer}\nやさしい解説：${q.explain}`).join('\n\n');
    const fallback=()=>{ const area=document.createElement('textarea'); area.value=text; area.setAttribute('readonly',''); area.style.position='fixed'; area.style.opacity='0'; document.body.appendChild(area); area.select(); let ok=false; try{ok=document.execCommand('copy');}catch(e){ok=false;} area.remove(); showMessage(ok?'コピーしました。':'コピーできませんでした。問題文を選択してコピーしてください。'); };
    if(navigator.clipboard&&window.isSecureContext){ navigator.clipboard.writeText(text).then(()=>showMessage('コピーしました。')).catch(fallback); } else { fallback(); }
  }
  function printTestPdf(){
    if(!state.result||!state.result.items){ showMessage('先にミニテストを生成してください。'); return; }
    const popup=window.open('', '_blank');
    if(!popup){ showMessage('PDF画面を開けませんでした。ポップアップを許可してください。'); return; }
    const questionCard=q=>`<article class="q ${q.format==='説明問題'?'q-explain':q.format==='短答'?'q-short':'q-choice'}"><div class="qtop"><span class="num">問題${state.result.items.indexOf(q)+1}</span></div><h2>${q.question}</h2>${q.choices?`<div class="choices">${q.choices.map((c,j)=>`<span>${String.fromCharCode(65+j)}　${c}</span>`).join('')}</div>`:''}<div class="work-label">${q.format==='説明問題'?'考え方を書きましょう。':q.format==='短答'?'答えを書きましょう。':'計算・メモ欄'}</div><div class="answer-line"></div></article>`;
    const answerCard=q=>`<article class="a"><div class="qtop"><span class="num">問題${state.result.items.indexOf(q)+1}</span></div><h2>${q.question}</h2><p class="correct"><b>正答</b>　${q.answer}</p><p><b>やさしい解説</b>　${q.explain}</p></article>`;
    const questions=`<div class="columns"><div class="column">${state.result.items.slice(0,3).map(questionCard).join('')}</div><div class="column">${state.result.items.slice(3).map(questionCard).join('')}</div></div>`;
    const answers=`<div class="columns"><div class="column">${state.result.items.slice(0,3).map(answerCard).join('')}</div><div class="column">${state.result.items.slice(3).map(answerCard).join('')}</div></div>`;
    const css='*{box-sizing:border-box}body{margin:0;color:#203040;font-family:-apple-system,BlinkMacSystemFont,"Noto Sans JP","Yu Gothic",sans-serif;line-height:1.7}.sheet{width:257mm;min-height:364mm;margin:0 auto;padding:17mm 19mm;page-break-after:always}header{display:flex;justify-content:space-between;align-items:end;border-bottom:4px solid #8ed0c1;padding-bottom:10px}.meta{font-size:23px;font-weight:700;color:#18324b;letter-spacing:.08em}.unit-meta{font-size:15px;font-weight:700;color:#18324b}.title{display:flex;align-items:center;gap:10px;margin:20px 0 10px}.title span{font-size:30px}.title h1{margin:0;font-size:30px;color:#18324b}.score-box{margin-left:auto;border:2px solid #18324b;border-radius:4px;min-width:42mm;height:14mm;padding:2mm 3mm;font-size:20px;text-align:right;color:#18324b}.score-box span{font-size:12px}.columns{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:12mm;align-items:start}.column{min-width:0}.q,.a{border:2px solid #dbe4ed;border-radius:14px;padding:11px 13px;margin:10px 0;background:#fbfdff;break-inside:avoid;min-height:50mm}.q:nth-child(odd),.a:nth-child(odd){border-color:#bfe5dc;background:#f5fffc}.qtop{display:flex;align-items:center;gap:8px}.num{display:inline-flex;align-items:center;justify-content:center;background:#18324b;color:#fff;border-radius:8px;min-width:27mm;height:9mm;padding:0 5px;font-size:14px;font-weight:800}.q h2,.a h2{font-size:16px;margin:7px 0;color:#203040}.choices{display:grid;grid-template-columns:1fr;gap:6px;margin:8px 0}.choices span{border:1px solid #dbe4ed;border-radius:8px;padding:5px 8px;background:#fff}.work-label{font-size:11px;color:#6b7b8d;margin-top:8px}.answer-line{height:38px;border-bottom:1px dashed #aebdca;margin-top:5px}.q-short .answer-line{height:55px}.q-explain .answer-line{height:82px}.a p{font-size:13px;margin:6px 0}.correct{background:#e8f7f1;border-radius:8px;padding:7px 10px;color:#146c4b}.a b{color:#18324b}@page{size:B4 portrait;margin:0}@media print{.sheet{margin:0}}';
    popup.document.write(`<!doctype html><html lang="ja"><head><meta charset="utf-8"><title>${state.unit} 練習問題</title><style>${css}</style></head><body><section class="sheet"><header><div class="meta">名前：　　　　　　　　　　　　　　　　</div><div class="unit-meta">${state.grade} ${state.subject}「${state.unit}」</div></header><div class="title"><span>✏️</span><h1>練習問題</h1><div class="score-box">　　　<span>点</span></div></div>${questions}</section><section class="sheet"><header><div class="unit-meta">${state.grade} ${state.subject}「${state.unit}」</div></header><div class="title"><span>🌟</span><h1>答え・やさしい解説</h1></div>${answers}</section><script>window.onload=function(){window.print();};<\/script></body></html>`); popup.document.close();
  }
  function buildWorksheet(){
    if(state.grade==='5年'&&state.subject==='算数'&&state.unit==='割合') return [
      {question:'200円の15%はいくらですか。式と答えを書きましょう。',answer:'30円',explain:'200×0.15＝30です。'},
      {question:'80人のうち男子が32人でした。男子は全体の何%ですか。',answer:'40%',explain:'32÷80＝0.4なので40%です。'},
      {question:'定価1,200円の25%引きの値段を求めましょう。',answer:'900円',explain:'25%引きは75%の値段なので、1200×0.75＝900円です。'},
      {question:'もとにする量が60、割合が0.4のとき、比べる量を求めましょう。',answer:'24',explain:'60×0.4＝24です。'},
      {question:'ある数の30%が18です。ある数を求めましょう。',answer:'60',explain:'18÷0.3＝60です。'}
    ];
    return [`${state.unit}で大切な言葉を一つ書きましょう。`,`「${state.unit}」で学んだことを使って答えましょう。`,`答えの理由や考え方を書きましょう。`,'学んだことを図や式で表しましょう。','今日の学習で分かったことを書きましょう。'].map(question=>({question,answer:'',explain:'学習内容を振り返りましょう。'}));
  }
  function renderWorksheetResult(){ if(!state.worksheetResult)return; const card=(q,i)=>`<article class="question"><div class="question-head"><span class="qno">${i+1}</span></div><p><strong>${q.question}</strong></p><p class="answer">正答：${q.answer||'記入内容を確認'}</p><p class="explain">やさしい解説：${q.explain}</p></article>`; el('#worksheet-result').innerHTML=`<div class="result"><h3>${state.grade} ${state.subject}「${state.unit}」ワークシート（${state.level}）</h3>${researchBasis}<div class="worksheet-preview"><div class="worksheet-column">${state.worksheetResult.slice(0,3).map((q,i)=>card(q,i)).join('')}</div><div class="worksheet-column">${state.worksheetResult.slice(3).map((q,i)=>card(q,i+3)).join('')}</div></div><div class="actions"><button class="primary" id="regenerate-worksheet">作り直す</button><button class="secondary" id="copy-worksheet">コピー</button><button class="secondary" id="save-worksheet-desk">マイ授業デスクに保存</button><button class="secondary" id="save-worksheet-pdf">PDFでローカル保存</button></div><p id="worksheet-message" class="notice" hidden></p></div>`; applyLabels(); }
  function copyWorksheet(){ const text=state.worksheetResult.map((q,i)=>`問題${i+1}：${q.question}\n正答：${q.answer}\nやさしい解説：${q.explain}`).join('\n\n'); navigator.clipboard?.writeText(text).then(()=>{const n=el('#worksheet-message');n.hidden=false;n.textContent='コピーしました。';}).catch(()=>{const n=el('#worksheet-message');n.hidden=false;n.textContent='コピーできませんでした。問題文を選択してコピーしてください。';}); }
  function saveWorksheetToDesk(){ try{const key='schoolpilot-review-tests';const all=JSON.parse(localStorage.getItem(key)||'[]').filter(x=>!(x.grade===state.grade&&x.subject===state.subject&&x.publisher===state.publisher&&x.unit===state.unit&&x.level===state.level));all.unshift({grade:state.grade,subject:state.subject,publisher:state.publisher,unit:state.unit,level:state.level,items:state.worksheetResult,savedAt:new Date().toISOString()});localStorage.setItem(key,JSON.stringify(all.slice(0,20)));const n=el('#worksheet-message');if(n){n.hidden=false;n.textContent='同じ内容がある場合は上書きして、マイ授業デスクに保存しました。';}}catch(e){const n=el('#worksheet-message');if(n){n.hidden=false;n.textContent='保存できませんでした。';}} }
  function renderSupportResult(type){ const isBoard=type==='board'; const title=isBoard?'板書例':'指導案・授業展開例'; const content=isBoard?['めあて：割合の求め方を考えよう','問題：120円の20%はいくら？','数直線で「もとにする量」と「比べられる量」を確認','割合＝比べられる量÷もとにする量','まとめ：割合は、もとにする量を1とみたときの比']:[]; const lesson=['導入 5分：身近な割合の場面を提示','問題提示 5分：何を1とみるか考える','個人思考 10分：数直線と式で表す','交流 15分：考え方を比べる','まとめ 5分：公式と言葉を整理','振り返り 5分：分かったことを書く']; const rows=isBoard?content:lesson; const box=el('.panel'); if(!box)return; let old=el('#support-result'); if(!old){old=document.createElement('div');old.id='support-result';old.className='support-result';box.appendChild(old);} old.innerHTML=`<div class="result"><h3>${state.grade} ${state.subject}「${state.unit}」${title}</h3><div class="support-paper">${rows.map((x,i)=>`<div class="support-row"><b>${i+1}</b><span>${x}</span></div>`).join('')}</div><div class="actions"><button class="primary" id="print-support" data-support-type="${type}">印刷</button><button class="secondary" id="save-support" data-support-type="${type}">マイ授業デスクに保存</button></div></div>`; }
