  function addBoardVisual(){ const paper=el('#support-result .support-paper'); if(!paper||el('#board-visual'))return; const rows=Array.from(paper.querySelectorAll('.support-row span')).map(x=>x.textContent||''); if(!rows.length)return; const textOf=x=>{const p=String(x||'').split('：');return {label:p.shift()||'板書',text:p.join('：')||String(x||'')};}; const parts=[textOf(rows[0]),textOf(rows[Math.min(1,rows.length-1)]),textOf(rows[rows.length-1])]; const icons={国語:'📖',算数:'🔢',理科:'🔬',社会:'🗺️',英語:'🔤'}; const middle=state.subject==='理科'?'🧪':state.subject==='社会'?'🗺️':state.subject==='英語'?'💬':icons[state.subject]||'📝'; paper.insertAdjacentHTML('beforebegin',`<div id="board-visual" class="board-visual"><div class="board-head">黒板イメージ</div><div class="board-columns"><div class="board-part"><span class="board-icon">${icons[state.subject]||'🎯'}</span><b>${parts[0].label}</b><p>${parts[0].text}</p></div><div class="board-part"><span class="board-icon">${middle}</span><b>${parts[1].label}</b><p>${parts[1].text}</p><div class="board-note">${rows.length>2?textOf(rows[2]).text:''}</div></div><div class="board-part"><span class="board-icon">✅</span><b>${parts[2].label}</b><p>${parts[2].text}</p></div></div></div>`); }
